def resource_balances_for_organization(
    self, organization_id: str
) -> dict[str, dict[str, int]]:
    """Locked copy of one organization's per-resource balances.

    Mirrors :meth:`Snapshot.resource_balances`: every resource the
    organization reserves maps to its ``capacity``, ``occupied`` (the
    total quantity it has reserved against it) and ``remaining``
    (``capacity - occupied``). The balances are computed inside the
    inventory lock from a consistent snapshot, so a read-only comparison
    never observes a partially applied commit.
    """
    with self._lock:
        reservations = [
            record
            for record in self._reservations.values()
            if record["organizationId"] == organization_id
        ]
        resource_ids = {record["resourceId"] for record in reservations}
        return {
            resource_id: {
                "capacity": self._capacities[resource_id],
                "occupied": sum(
                    record["quantity"]
                    for record in reservations
                    if record["resourceId"] == resource_id
                ),
                "remaining": self._capacities[resource_id]
                - sum(
                    record["quantity"]
                    for record in reservations
                    if record["resourceId"] == resource_id
                ),
            }
            for resource_id in resource_ids
        }

