        organization_id
    )
    right_balances = (
        right_branch.reservations.resource_balances_for_organization(
            organization_id
        )
    )
    result = compare_branch_resources(left_balances, right_balances)
    self._write_json(HTTPStatus.OK, result, newline=True)

